  public static String escapeQuotesChecked(final String str) {
    final int len = str.length();
    int from = 0;
    do {
      from = str.indexOf('"', from);
      if (from < 0) {
        return str;
      }
      int i = from - 1;
      if (i < 0) {
        return escapeQuotes(str, from);
      }
      if (str.charAt(i) == '\\') {
        int escapes = 1;
        while (--i >= 0) {
          if (str.charAt(i) == '\\') {
            ++escapes;
          } else {
            break;
          }
        }
        if ((escapes & 1) == 0) {
          return escapeQuotes(str, from);
        }
      } else {
        return escapeQuotes(str, from);
      }
    } while (++from < len);
    return str;
  }

